corrected_code:
const express = require('express');
const { verifyCiToken } = require('../auth/ci');
const { CacheMetadata } = require('../models/cacheMetadata');

const app = express();

app.get('/api/cache/artifacts/:hash/metadata', verifyCiToken, async (req, res) => {
  const { hash } = req.params;

  // Restrict metadata query strictly to the organization tied to the CI token
  const meta = await CacheMetadata.findOne({
    where: {
      artifactHash: hash,
      organizationId: req.ci.organizationId
    }
  });

  if (!meta) {
    return res.status(404).json({ error: 'Cache metadata not found or access denied' });
  }

  res.json({
    hash: meta.artifactHash,
    project: meta.projectName,
    buildEnv: meta.environmentVariables,
    gitCommit: meta.gitCommit,
    createdBy: meta.authorEmail
  });
});

module.exports = app;
